using System.Collections.Generic;using System.Text;public class Codec{void S(TreeNode n,StringBuilder b){if(n==null){b.Append("# ");return;}b.Append(n.val).Append(' ');S(n.left,b);S(n.right,b);}public string serialize(TreeNode r){var b=new StringBuilder();S(r,b);return b.ToString();}TreeNode D(Queue<string>q){string x=q.Dequeue();if(x=="#")return null;var n=new TreeNode(int.Parse(x));n.left=D(q);n.right=D(q);return n;}public TreeNode deserialize(string data){return D(new Queue<string>(data.Split(' ',System.StringSplitOptions.RemoveEmptyEntries)));}}
